/*
	Unit tests for the clone REST client's URL construction.

	meadow-endpoints pluralizes the entity name only on the list-shaped read routes
	(`<Entity>s/By/...`, `<Entity>s/Count/...`); every singular-record and upsert route is
	registered against the bare entity name. Getting that wrong yields a 405 rather than a 404,
	which reads like a permissions problem and not a routing one, so each method is pinned here
	against the route it is meant to reach.
*/

const Chai = require('chai');
const Expect = Chai.expect;

const libHTTP = require('http');
const libFable = require('fable');

const libMeadowCloneRestClient = require('../source/services/clone/Meadow-Service-RestClient.js');

const MOCK_PORT = 18101;
const MOCK_BASE_URL = `http://localhost:${MOCK_PORT}/1.0/`;

suite
(
	'Meadow Integration - Clone REST Client Routes',
	() =>
	{
		let _Server = false;
		let _RequestLog = [];

		setup
		(
			(fDone) =>
			{
				_RequestLog = [];
				_Server = libHTTP.createServer
				(
					(pRequest, pResponse) =>
					{
						let tmpBody = '';
						pRequest.on('data', (pChunk) => { tmpBody += pChunk; });
						pRequest.on('end',
							() =>
							{
								_RequestLog.push({ Method: pRequest.method, URL: pRequest.url });
								pResponse.writeHead(200, { 'Content-Type': 'application/json' });
								pResponse.end('[]');
							});
					});
				_Server.listen(MOCK_PORT, fDone);
			}
		);

		teardown
		(
			(fDone) =>
			{
				if (_Server)
				{
					return _Server.close(() => { _Server = false; return fDone(); });
				}
				return fDone();
			}
		);

		const buildClient = () =>
		{
			const tmpFable = new libFable({ Product: 'MeadowIntegrationRestClientRouteTest' });
			tmpFable.serviceManager.addServiceType('MeadowCloneRestClient', libMeadowCloneRestClient);
			return tmpFable.serviceManager.instantiateServiceProvider('MeadowCloneRestClient', { ServerURL: MOCK_BASE_URL });
		};

		test
		(
			'a bulk upsert addresses the singular entity, matching the registered /Upserts route',
			(fDone) =>
			{
				buildClient().upsertEntities('Book', [ { IDBook: 1 }, { IDBook: 2 } ],
					() =>
					{
						Expect(_RequestLog.length).to.equal(1);
						Expect(_RequestLog[0].Method).to.equal('PUT');
						Expect(_RequestLog[0].URL).to.equal('/1.0/Book/Upserts');
						return fDone();
					});
			}
		);

		test
		(
			'a single upsert addresses the singular entity',
			(fDone) =>
			{
				buildClient().upsertEntity('Book', { IDBook: 1 },
					() =>
					{
						Expect(_RequestLog[0].Method).to.equal('PUT');
						Expect(_RequestLog[0].URL).to.equal('/1.0/Book/Upsert');
						return fDone();
					});
			}
		);

		test
		(
			'a create posts to the bare entity',
			(fDone) =>
			{
				buildClient().createEntity('Book', { Title: 'A Book' },
					() =>
					{
						Expect(_RequestLog[0].Method).to.equal('POST');
						Expect(_RequestLog[0].URL).to.equal('/1.0/Book');
						return fDone();
					});
			}
		);

		test
		(
			'an update puts to the bare entity',
			(fDone) =>
			{
				buildClient().updateEntity('Book', { IDBook: 1 },
					() =>
					{
						Expect(_RequestLog[0].Method).to.equal('PUT');
						Expect(_RequestLog[0].URL).to.equal('/1.0/Book');
						return fDone();
					});
			}
		);

		test
		(
			'a read by GUID uses the plural list route, which is the one meadow pluralizes',
			(fDone) =>
			{
				buildClient().getEntityByGUID('Book', 'abc-123',
					() =>
					{
						Expect(_RequestLog[0].Method).to.equal('GET');
						Expect(_RequestLog[0].URL).to.equal('/1.0/Books/By/GUIDBook/abc-123/0/1');
						return fDone();
					});
			}
		);
	}
);
